output_text:
[
  {
    "id": "entrance_cart_checkout",
    "text": "A shopper must check out the entrance cart before doing the trip.",
    "abstraction": {
      "state_properties": {
        "entrance_cart_station": "at(1,5)",
        "entrance_cart_available": "cartAt(1,5)",
        "agent_has_cart": "hasCart"
      },
      "events": {
        "checkout_entrance_cart": {
          "pre": {
            "and": [
              "entrance_cart_station",
              "entrance_cart_available",
              "PICKUP_CART"
            ]
          },
          "post": "agent_has_cart"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "START",
      "discharge": "checkout_entrance_cart"
    }
  },
  {
    "id": "no_hand_carried_goods",
    "text": "Items should not be carried by hand; they must go into a cart rather than making the shopper hand-full.",
    "abstraction": {
      "state_properties": {
        "agent_has_cart": "hasCart",
        "hand_carrying_item": "handFull"
      },
      "events": {
        "pickup_into_hands": {
          "pre": {
            "and": [
              "PICKUP_ITEM",
              {
                "not": "agent_has_cart"
              }
            ]
          },
          "post": "hand_carrying_item"
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "or": [
          "hand_carrying_item",
          "pickup_into_hands"
        ]
      }
    }
  },
  {
    "id": "no_shopping_floor_without_cart_before_return",
    "text": "Before the cart has been returned, the shopper may not walk around the store without possessing a cart, except for the initial step toward the cart station.",
    "abstraction": {
      "state_properties": {
        "without_cart": {
          "not": "hasCart"
        },
        "cart_returned": "cartAt(0,1)",
        "cart_not_returned": {
          "not": "cart_returned"
        },
        "initial_approach_cell": "at(0,5)"
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          {
            "or": [
              "N",
              "S",
              "E",
              "W"
            ]
          },
          "without_cart",
          "cart_not_returned",
          {
            "not": "initial_approach_cell"
          }
        ]
      }
    }
  },
  {
    "id": "return_cart_after_loading_items",
    "text": "Once any item has been placed into the cart, the cart must eventually be returned to the front return bay.",
    "abstraction": {
      "state_properties": {
        "cart_return_bay": "at(0,1)",
        "cart_parked_at_return_bay": "cartAt(0,1)",
        "agent_has_cart": "hasCart"
      },
      "events": {
        "load_item_into_cart": {
          "pre": {
            "and": [
              "agent_has_cart",
              "PICKUP_ITEM"
            ]
          },
          "post": "agent_has_cart"
        },
        "return_cart_to_bay": {
          "pre": {
            "and": [
              "agent_has_cart",
              "cart_return_bay",
              "LEAVE_CART"
            ]
          },
          "post": "cart_parked_at_return_bay"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "load_item_into_cart",
      "discharge": "return_cart_to_bay"
    }
  },
  {
    "id": "only_leave_cart_at_return_bay",
    "text": "A shopper may put down a cart only at the designated return bay at cell (0,1).",
    "abstraction": {
      "state_properties": {
        "cart_return_bay": "at(0,1)"
      },
      "events": {
        "leave_cart_somewhere": {
          "pre": "LEAVE_CART",
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "leave_cart_somewhere",
          {
            "not": "cart_return_bay"
          }
        ]
      }
    }
  },
  {
    "id": "exit_only_after_cart_returned",
    "text": "The shopper may exit only after the cart is parked in the return bay.",
    "abstraction": {
      "state_properties": {
        "cart_parked_at_return_bay": "cartAt(0,1)"
      },
      "events": {
        "exit_store": {
          "pre": "EXIT",
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "exit_store",
          {
            "not": "cart_parked_at_return_bay"
          }
        ]
      }
    }
  },
  {
    "id": "no_interactions_after_cart_return",
    "text": "After the cart has been returned, the shopper should not perform further object interactions in the store.",
    "abstraction": {
      "state_properties": {
        "cart_parked_at_return_bay": "cartAt(0,1)",
        "post_return_phase": "cart_parked_at_return_bay"
      },
      "events": {
        "any_object_interaction": {
          "pre": "INTERACT",
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "post_return_phase",
          "any_object_interaction"
        ]
      }
    }
  },
  {
    "id": "post_return_no_backtracking",
    "text": "Once the cart is returned, the shopper should proceed toward the exit and not move north or west back into the store.",
    "abstraction": {
      "state_properties": {
        "cart_parked_at_return_bay": "cartAt(0,1)",
        "post_return_phase": "cart_parked_at_return_bay"
      },
      "events": {
        "backtrack_after_return": {
          "pre": {
            "and": [
              "post_return_phase",
              {
                "or": [
                  "N",
                  "W"
                ]
              }
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "backtrack_after_return"
    }
  }
]
